// Aseguramos que todo sean números (Floats)
msg.payload = [
    {
            temperature: parseFloat(msg.payload.temperature),
                    humidity: parseFloat(msg.payload.humidity),
                            pressure: parseFloat(msg.payload.pressure),
                                    iaq: parseFloat(msg.payload.iaq),
                                            iaq_accuracy: parseFloat(msg.payload.iaqAccuracy),
                                                    gas_resistance: parseFloat(msg.payload.gasResistance)
                                                        },
                                                            {
                                                                    location: msg.payload.location || "unknown",
                                                                            device_id: msg.payload.device_id || "unknown"
                                                                                }
                                                                                ];

                                                                                // Nombre de la tabla (Measurement)
                                                                                msg.measurement = "clima";

                                                                                return msg

// El payload ya viene listo desde el nodo anterior.
// Solo lo pasamos tal cual.
return msg;

// Recuperamos la API Key que viene DENTRO del mensaje del ESP32
var dynamicKey = msg.payload.ts_api_key;

// Validación de seguridad: Si no trae llave, no enviamos
if (!dynamicKey || dynamicKey === "") {
    node.warn("⚠️ Mensaje sin API Key de ThingSpeak. Ignorando.");
    return null; 
}

// Mapeo para ThingSpeak
msg.payload = {
    api_key: dynamicKey, // <--- Usamos la variable dinámica
    field1: msg.payload.temperature,
    field2: msg.payload.humidity,
    field3: msg.payload.pressure,
    field4: msg.payload.iaq
    // Agrega más fields si quieres
};

return msg;

// Usamos 'flow' directamente para guardar los datos globales
// Recuperamos el diccionario de dispositivos (o creamos uno nuevo)
var devices = flow.get('devices') || {};

// Validación de seguridad
if (msg.payload && (msg.payload.temperature !== undefined) && msg.payload.location) {
    var loc = msg.payload.location;

    // Si es la primera vez que vemos este dispositivo, inicializamos sus variables
    if (!devices[loc]) {
        devices[loc] = {
            count: 0,
            s_temp: 0, s_hum: 0, s_press: 0, s_iaq: 0,
            s_static: 0, s_co2: 0, s_voc: 0, s_gas: 0, s_gasP: 0, s_rawT: 0, s_rawH: 0,
            last_acc: 0, last_stab: 0, last_run: 0
        };
    }

    var d = devices[loc]; // Atajo para trabajar con ESTE dispositivo

    // Acumular valores (Sumas)
    d.s_temp += parseFloat(msg.payload.temperature);
    d.s_hum += parseFloat(msg.payload.humidity);
    d.s_press += parseFloat(msg.payload.pressure);
    d.s_iaq += parseFloat(msg.payload.iaq);
    d.s_static += parseFloat(msg.payload.staticIaq);
    d.s_co2 += parseFloat(msg.payload.co2Equivalent);
    d.s_voc += parseFloat(msg.payload.breathVocEquivalent);
    d.s_gas += parseFloat(msg.payload.gasResistance);
    d.s_gasP += parseFloat(msg.payload.gasPercentage);
    d.s_rawT += parseFloat(msg.payload.rawTemperature);
    d.s_rawH += parseFloat(msg.payload.rawHumidity);

    // Contar muestra
    d.count++;

    // Guardar último estado conocido
    d.last_acc = msg.payload.iaqAccuracy;
    d.last_stab = msg.payload.stabStatus;
    d.last_run = msg.payload.runInStatus;

    // Guardar cambios en memoria de Flujo
    flow.set('devices', devices);
}

return null;

var date = new Date();
var minutes = date.getMinutes();

// Ejecutar solo al minuto 0
// (Cambia 'minutes === 0' a 'true' si quieres probar ahora mismo)
if (minutes === 0) { 

    // Usamos 'flow' directamente
    var devices = flow.get('devices') || {};
    var outputMessages = []; // Aquí guardaremos los mensajes para cada hoja

    // Obtenemos la lista de ubicaciones registradas
    var locations = Object.keys(devices);

    if (locations.length === 0) return null;

    // Función auxiliar para promediar y formatear
    function fmt(val, n) { return (val / n).toFixed(2); }

    // Recorremos cada dispositivo
    for (var i = 0; i < locations.length; i++) {
        var loc = locations[i];
        var d = devices[loc];

        // Solo enviamos si tuvo datos esta hora
        if (d.count > 0) {
            var msgPayload = {
                // --- Metadatos ---
                fechaHora: new Date().toISOString().replace('T', ' ').substring(0, 19),
                location: loc, 

                // --- Promedios ---
                temperature: fmt(d.s_temp, d.count),
                humidity: fmt(d.s_hum, d.count),
                pressure: fmt(d.s_press, d.count),
                iaq: fmt(d.s_iaq, d.count),

                staticIaq: fmt(d.s_static, d.count),
                co2Equivalent: fmt(d.s_co2, d.count),
                breathVocEquivalent: fmt(d.s_voc, d.count),

                rawTemperature: fmt(d.s_rawT, d.count),
                rawHumidity: fmt(d.s_rawH, d.count),

                gasResistance: fmt(d.s_gas, d.count),
                gasPercentage: fmt(d.s_gasP, d.count),

                // --- Estados ---
                iaqAccuracy: d.last_acc,
                stabStatus: d.last_stab,
                runInStatus: d.last_run,

                samples: d.count
            };

            // Agregamos el mensaje a la lista de salida
            outputMessages.push({ payload: msgPayload });
        }
    }

    // RESETEAR TODO: Borramos el diccionario en 'flow' para empezar limpios
    flow.set('devices', {});

    // Node-RED enviará estos mensajes uno tras otro
    return [ outputMessages ];
}

return null;

// Usamos el contexto del flujo para recordar cuándo pasó cada dispositivo
var lastSent = flow.get('ts_last_sent') || {};

// Identificamos el dispositivo (por ubicación o ID)
var deviceKey = msg.payload.location || "unknown";
var now = Date.now();

// Tiempo de espera en milisegundos (20 segundos)
var cooldown = 20000; 

// Verificamos si este dispositivo específico puede pasar
if (!lastSent[deviceKey] || (now - lastSent[deviceKey] > cooldown)) {

    // ¡Luz Verde! Actualizamos su última hora de paso
    lastSent[deviceKey] = now;
    flow.set('ts_last_sent', lastSent);

    return msg; // Dejar pasar el mensaje
}

// ¡Luz Roja! Aún no han pasado 20s para ESTE dispositivo
return null; // Bloquear mensaje
